// src/pages/client/MyLoan.js
import React, { useState, useEffect } from 'react';
import { loansAPI, repaymentsAPI } from '../../services/api';
import { CreditCard, CheckCircle, Clock, AlertCircle } from 'lucide-react';

const fmtMoney = (n) => new Intl.NumberFormat('en-US').format(n || 0) + ' FCFA';
const fmtDate = (d) => d ? new Date(d).toLocaleDateString('en-US', { day: '2-digit', month: 'long', year: 'numeric' }) : '—';

const statusBadge = (s) => {
  const map = { ACTIVE: ['badge-info', 'Active'], COMPLETED: ['badge-success', 'Paid'], OVERDUE: ['badge-danger', 'Overdue'] };
  const [cls, label] = map[s] || ['badge-gray', s];
  return <span className={`badge ${cls}`}>{label}</span>;
};

export default function MyLoan() {
  const [loans, setLoans] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loansAPI.getMyLoan().then(r => { setLoans(r.data.data); setLoading(false); }).catch(() => setLoading(false));
  }, []);

  if (loading) return <div className="page-loader"><div className="spinner" style={{ width: 32, height: 32 }} /></div>;

  if (!loans.length) return (
    <div className="fade-in" style={{ textAlign: 'center', marginTop: 80 }}>
      <CreditCard size={48} style={{ opacity: 0.2, marginBottom: 16 }} />
      <h2 style={{ color: 'var(--gray-500)' }}>No loans found</h2>
      <p style={{ color: 'var(--gray-400)', fontSize: 14 }}>You don't have any loans yet.</p>
    </div>
  );

  return (
    <div className="fade-in">
      <div style={{ marginBottom: 28 }}>
        <h1 style={{ fontSize: 22, marginBottom: 4 }}>My Loan</h1>
        <p style={{ color: 'var(--gray-500)', fontSize: 13 }}>Information about your current loans</p>
      </div>

      {loans.map((loan) => {
        const totalPaid = (loan.repayments || []).reduce((s, r) => s + r.amount, 0);
        const remaining = Math.max(0, loan.totalRepayable - totalPaid);
        const progress = Math.min(100, Math.round((totalPaid / (loan.totalRepayable || 1)) * 100));

        return (
          <div key={loan._id} className="card" style={{ marginBottom: 20, padding: 24 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 24 }}>
              <div>
                <div style={{ fontSize: 28, fontFamily: 'var(--font-heading)', fontWeight: 700, color: 'var(--gray-900)', marginBottom: 4 }}>
                  {fmtMoney(loan.amount)}
                </div>
                <div style={{ fontSize: 13, color: 'var(--gray-500)' }}>Loan from {fmtDate(loan.startDate)}</div>
              </div>
              {statusBadge(loan.status)}
            </div>

            {/* Details grid */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 14, marginBottom: 24 }}>
              {[
                { label: 'Interest Rate', value: `${loan.interestRate}%` },
                { label: 'Duration', value: `${loan.duration} months` },
                { label: 'Total Interest', value: fmtMoney(loan.interest) },
                { label: 'Total Repayable', value: fmtMoney(loan.totalRepayable) },
                { label: 'Already Paid', value: fmtMoney(totalPaid), success: true },
                { label: 'Remaining', value: fmtMoney(remaining), danger: remaining > 0 },
              ].map(({ label, value, success, danger }) => (
                <div key={label} style={{ background: 'var(--gray-50)', borderRadius: 8, padding: '12px 14px', border: '1px solid var(--gray-100)' }}>
                  <div style={{ fontSize: 11, color: 'var(--gray-400)', fontWeight: 600, textTransform: 'uppercase', marginBottom: 4 }}>{label}</div>
                  <div style={{ fontSize: 15, fontWeight: 700, color: success ? 'var(--success)' : danger ? 'var(--danger)' : 'var(--gray-800)' }}>{value}</div>
                </div>
              ))}
            </div>

            {/* Progress */}
            <div>
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, color: 'var(--gray-500)', marginBottom: 8 }}>
                <span>Repayment Progress</span>
                <span style={{ fontWeight: 600 }}>{progress}%</span>
              </div>
              <div style={{ background: 'var(--gray-200)', borderRadius: 6, height: 10, overflow: 'hidden' }}>
                <div style={{
                  height: '100%', borderRadius: 6,
                  background: loan.status === 'COMPLETED' ? 'var(--success)' : loan.status === 'OVERDUE' ? 'var(--danger)' : 'var(--accent)',
                  width: `${progress}%`, transition: 'width 0.8s ease',
                }} />
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}
